const funnelTargets = ['TOFU', 'MOFU', 'BOFU'];
const funnelInstructions = {
  TOFU: 'Informa y contextualiza. No ofrezcas servicios. Cierra con una pregunta específica sobre la noticia.',
  MOFU: 'Convierte la noticia en criterios para evaluar una decisión, riesgo u oportunidad. Usa una invitación comercial suave.',
  BOFU: 'Relaciona la noticia con una necesidad concreta que Tu Partner TI pueda resolver. Explica la ayuda de forma directa y sobria.'
};
const keywords = ['ai', 'artificial intelligence', 'cyber', 'security', 'cloud', 'software', 'data', 'digital', 'automation', 'startup', 'product', 'innovation', 'technology', 'robot', 'blockchain', 'fintech', 'infrastructure'];

const candidates = items.map((item, index) => {
  const text = `${item.json.title ?? ''} ${item.json.contentSnippet ?? ''}`.toLowerCase();
  const score = keywords.reduce((total, keyword) => total + (text.includes(keyword) ? 1 : 0), 0);
  const timestamp = Date.parse(item.json.isoDate ?? item.json.pubDate ?? '') || 0;
  const domain = String(item.json.link ?? '').match(/^https?:\/\/([^/]+)/i)?.[1]?.replace(/^www\./, '') ?? `unknown-${index}`;
  return { item, index, score, timestamp, domain };
}).filter((candidate) => candidate.score > 0);

candidates.sort((a, b) => b.score - a.score || b.timestamp - a.timestamp || a.index - b.index);

const selected = [];
const usedDomains = new Set();
for (const candidate of candidates) {
  if (!usedDomains.has(candidate.domain)) {
    selected.push(candidate);
    usedDomains.add(candidate.domain);
  }
  if (selected.length === 3) break;
}

for (const candidate of candidates) {
  if (selected.length === 3) break;
  if (!selected.includes(candidate)) selected.push(candidate);
}

return selected.map(({ item }, index) => {
  const funnelTarget = funnelTargets[index];
  const originalSnippet = String(item.json.contentSnippet ?? item.json.content ?? '').replace(/\s+/g, ' ').trim().slice(0, 1800);
  return {
    json: {
      ...item.json,
      funnel_target: funnelTarget,
      original_content_snippet: originalSnippet,
      contentSnippet: `${originalSnippet}\n\nINSTRUCCIÓN EDITORIAL OBLIGATORIA: genera este post como ${funnelTarget}. ${funnelInstructions[funnelTarget]}`
    }
  };
});

const raw = String($json.output ?? $json.choices?.[0]?.message?.content ?? '').trim();
const jsonMatch = raw.match(/\{[\s\S]*\}/);
if (!jsonMatch) throw new Error('La IA no devolvió un objeto JSON. No se escribirá ninguna fila incompleta.');

let parsed;
try {
  parsed = JSON.parse(jsonMatch[0]);
} catch (error) {
  throw new Error(`JSON inválido devuelto por la IA: ${error.message}`);
}

const source = $('Replace Me').item.json;
const target = String(source.funnel_target ?? parsed.funnel ?? '').trim().toUpperCase();
const trailing = raw.slice((jsonMatch.index ?? 0) + jsonMatch[0].length).replace(/```/g, '').trim();
const externalHashtags = trailing.match(/(?:#\S+\s*){2,}/)?.[0]?.trim() ?? '';
let copy = String(parsed.copy ?? '').trim();
if (externalHashtags && !/#\S+/.test(copy)) copy = `${copy}\n\n${externalHashtags}`;

const result = {
  ...source,
  generation_provider: $json.choices?.[0]?.message?.content ? 'OpenAI fallback' : 'Groq',
  funnel: target,
  titulo: String(parsed.titulo ?? '').trim(),
  copy,
  visual_prompt: String(parsed.visual_prompt ?? '').trim(),
  cta: String(parsed.cta ?? '').trim()
};

const missing = ['funnel', 'titulo', 'copy', 'visual_prompt', 'cta'].filter((field) => !result[field]);
if (missing.length) throw new Error(`Respuesta incompleta de la IA. Faltan: ${missing.join(', ')}. No se escribirá la fila.`);
if (!['TOFU', 'MOFU', 'BOFU'].includes(result.funnel)) throw new Error(`Funnel inválido: ${result.funnel}`);

return [{ json: result }];

const errorText = JSON.stringify($json);
if (!/(too many requests|rate limit|429|quota|tokens per day|tpd)/i.test(errorText)) {
  throw new Error(`Groq falló por una causa que no autoriza contingencia: ${errorText.slice(0, 500)}`);
}

return [{
  json: {
    ...$('Replace Me').item.json,
    groq_error: errorText.slice(0, 1500)
  }
}];

